// Process UI Component Analysis Data
const analysis = $input.first().json;

// Validate required fields
const requiredFields = ['component_id', 'component_name', 'crew_member', 'analysis_data'];
const missingFields = requiredFields.filter(field => !analysis[field]);

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Process and enrich analysis data
const processedAnalysis = {
  component_id: analysis.component_id,
  component_name: analysis.component_name,
  crew_member: analysis.crew_member,
  analysis_data: {
    embodiment_experience: analysis.analysis_data.embodiment_experience || '',
    functional_insights: analysis.analysis_data.functional_insights || [],
    data_display_capabilities: analysis.analysis_data.data_display_capabilities || [],
    user_interaction_patterns: analysis.analysis_data.user_interaction_patterns || [],
    enhancement_recommendations: analysis.analysis_data.enhancement_recommendations || []
  },
  enhancement_recommendations: analysis.enhancement_recommendations || [],
  implementation_status: analysis.implementation_status || 'pending',
  metadata: {
    analysis_timestamp: new Date().toISOString(),
    analysis_id: `ui_analysis_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    crew_count: 9,
    system_version: '1.0.0'
  }
};

return [{ json: processedAnalysis }];

// Generate embeddings for crew memory vectors
const analysis = $input.first().json;

// Create memory content for embedding
const memoryContent = `
Component: ${analysis.component_name}
Crew Member: ${analysis.crew_member}
Embodiment Experience: ${JSON.stringify(analysis.analysis_data.embodiment_experience)}
Functional Insights: ${JSON.stringify(analysis.analysis_data.functional_insights)}
Enhancement Recommendations: ${JSON.stringify(analysis.enhancement_recommendations)}
`;

// Prepare memory vector data
const memoryVector = {
  crew_member: analysis.crew_member,
  memory_type: 'ui_component_analysis',
  memory_content: memoryContent,
  metadata: {
    component_id: analysis.component_id,
    component_name: analysis.component_name,
    analysis_id: analysis.metadata.analysis_id,
    timestamp: analysis.metadata.analysis_timestamp
  }
};

return [{ json: memoryVector }];

// Create response with success confirmation
const result = $input.first().json;

const response = {
  success: true,
  message: 'UI component analysis stored successfully',
  analysis_id: result.metadata?.analysis_id || 'unknown',
  component: result.component_name,
  crew_member: result.crew_member,
  storage_status: {
    supabase: 'stored',
    memory_vectors: 'stored',
    timestamp: new Date().toISOString()
  },
  next_steps: [
    'Analysis available for retrieval',
    'Memory vectors ready for similarity search',
    'Enhancement recommendations can be implemented'
  ]
};

return [{ json: response }];
